		if len(req.InputTokens) > 300 && snap.FreeKVBlocks > 0 {
			headroom := float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 350.0)
			scores[snap.ID] *= (0.55 + 0.45*headroom)
		}

